// AutoSNS形式 or 直接JSON形式の両方に対応
const body = $input.first().json.body || $input.first().json;

// AutoSNS形式: form_data[form-N] / 直接: date, time
let dateRaw = body.date || body['form_data[form-date]'] || null;
let timeRaw = body.time || body['form_data[form-time]'] || null;
const uid = body.uid || null;
const nickname = body['user_data[nickname]'] || body.name || 'ユーザー';

// 日付整形
const formatDate = (v) => {
  if (!v) return null;
  if (/^\d{8}$/.test(v)) {
    return `${v.slice(0,4)}-${v.slice(4,6)}-${v.slice(6,8)}`;
  }
  const nums = v.match(/\d+/g);
  if (!nums || nums.length < 3) return null;
  return `${nums[0]}-${nums[1].padStart(2,'0')}-${nums[2].padStart(2,'0')}`;
};

// 時間整形
const formatTime = (v) => {
  if (!v || v === 'わからない' || v === '不明') return null;
  const nums = v.match(/\d+/g);
  if (!nums || nums.length < 2) return null;
  return `${nums[0].padStart(2,'0')}:${nums[1].padStart(2,'0')}`;
};

const date = formatDate(dateRaw);
const time = formatTime(timeRaw);

if (!date) {
  return [{ json: { error: true, message: '生年月日が取得できませんでした' } }];
}

return [{
  json: {
    date,
    time,
    uid,
    nickname
  }
}];

// BaZi APIレスポンスを整形してAIに渡すコンテキストを作成
const bazi = $input.first().json;
const nickname = $('入力整形').first().json.nickname;

// AIに渡す命式サマリー
const context = JSON.stringify({
  pillars: bazi.pillars,
  fiveElements: bazi.fiveElements,
  stars: {
    dayMaster: bazi.stars.dayMaster,
    tenGodSummary: bazi.stars.tenGodSummary
  }
}, null, 2);

return [{
  json: {
    nickname,
    baziContext: context,
    baziRaw: bazi
  }
}];

// AIレスポンスからレポートテキストを抽出
const raw = $input.first().json;
let reportText = '';

// n8n OpenAI node output format
if (raw.output && Array.isArray(raw.output)) {
  raw.output.forEach(msg => {
    if (msg.content && Array.isArray(msg.content)) {
      msg.content.forEach(block => {
        if (block.text) reportText += block.text;
      });
    }
  });
} else if (typeof raw.text === 'string') {
  reportText = raw.text;
} else if (typeof raw.content === 'string') {
  reportText = raw.content;
}

const nickname = $('入力整形').first().json.nickname;
const uid = $('入力整形').first().json.uid;

return [{
  json: {
    report: reportText.trim(),
    nickname,
    uid
  }
}];
